window.__reformedWorks["schaff_creeds3_02"] = {"id":"schaff_creeds3_02","a":"Schaff, Philip","t":"The Formula of Concord. A.D. 1576 (1584)","u":"https://ccel.org/ccel/schaff/creeds3","c":[{"t":"The Formula of Concord. A.D. 1576 (1584)","s":[{"t":"","p":["{Die Concordien-Formel.)","(THE EPITOME.)","[The Formula of Concord was originally written in the German language, 1576, and published at Dresden, 1580. It was translated into Latin by Lucas Osiander, 1680; but the translation was very defective, and was revised by two of the authors—first by Selnecker for the German-Latin edition of the Book of Concord, 1582, then more fully by Chemnitz, 1583; and in this doubly improved form it became the authorized text, published in the first authentic Latin edition of the Book of Concord, Leipzig, 1584. We give this text, with a new English translation made for this work from the German and Latin compared, and adapted to the style of the age of composition. The Epitome contains, in clear and concise form, all that is necessary for this collection; and hence we omit the lengthy Solid Repetition and Declaration, which merely repeats more fully the same articles, and fortifies them by ample quotations from the Scriptures, the fathers, the older Lutheran symbols, and the private writings of Luther, with an appendix of patristic testimonies for the doctrine of the communicatio idiomatum. See Vol. I. § 45, pp.258 sqq.]"]}]}]};
